import{createIntegrationSetupUi}from"./shared/ui.js";import{setupIntegration}from"./registry.js";import{describeIntegrationSetupEnvironment,integrationSetupEnvironment}from"./shared/environment.js";import{detectDeployment,projectResolutionFromDeployment}from"#setup/project-resolution.js";import{getVercelAuthStatus}from"#setup/vercel-project.js";import{interactiveAsker}from"#setup/ask.js";const defaultDeps={detectDeployment,getVercelAuthStatus};async function runIntegrationSetup(e,t,n=defaultDeps){let r=setupIntegration(e);t.prompter.intro(`Set up ${r.label}`),t.prompter.log.message(`Checking Vercel setup...`);let[i,a]=await Promise.all([n.detectDeployment(t.appRoot,{signal:t.signal}),n.getVercelAuthStatus(t.appRoot,{signal:t.signal})]),o=integrationSetupEnvironment(a,projectResolutionFromDeployment(i));return t.prompter.log.info(describeIntegrationSetupEnvironment(o)),await r.setup({environment:o,appRoot:t.appRoot,ui:createIntegrationSetupUi({asker:interactiveAsker(t.prompter),prompter:t.prompter}),yes:t.yes,signal:t.signal})}export{runIntegrationSetup};